import type { VirtualItem } from '@tanstack/react-virtual';
import clsx from 'clsx';
import React, { useLayoutEffect, useRef } from 'react';
import { Row } from 'react-table';

import { useContainerSize } from '../../../core/hooks/useContainerSize.js';

// Table typings are still based on community types which are not that great,
// need to disable no-explicit-any for the plugin file.
/* eslint-disable @typescript-eslint/no-explicit-any */

interface ExpandableRowWrapperProps {
  /** Data of the row that is being expanded. */
  row: Row<any>;

  /** Render function of the expand part. */
  render: (renderProps: { row: Record<string, any> }) => JSX.Element;

  /**
   * Virtualized row item to enable virtualizer.
   * Needs to be optional as it will take one render cycle to get to the newly
   * virtualized elements.
   */
  virtualRow: VirtualItem;

  /** Measure callback for the virtualizer. */
  rowVirtualizerMeasureElement: (node: Element | null) => void;
}

export const ExpandableRowWrapper = ({
  row,
  render,
  virtualRow,
  rowVirtualizerMeasureElement,
  ...remainingProps
}: ExpandableRowWrapperProps) => {
  const measureRef = useRef<HTMLDivElement | null>(null);
  // width of the corresponding expandable row
  const rowWidth =
    measureRef.current?.previousElementSibling?.getBoundingClientRect().width;
  // Keep track of the containers height and recall measure every time in
  // order to enable dynamic content height in the expandable rows.
  const { height } = useContainerSize(measureRef);

  useLayoutEffect(() => {
    rowVirtualizerMeasureElement(measureRef.current);
  }, [height, virtualRow]);

  return (
    <div
      {...remainingProps}
      id={row.ariaControls}
      ref={measureRef}
      className={clsx('strato-table-row-expandable')}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: rowWidth,
        transform: `translateY(${virtualRow?.start}px)`,
      }}
    >
      {render({ row: row.original })}
    </div>
  );
};
